public.prepare_deletion_request:
declare
  request_row public.data_requests%rowtype;
  storage_objects jsonb;
  first_at timestamptz;
begin
  select * into request_row
  from public.data_requests
  where id = p_request_id
    and kind = 'deletion'
    and status = 'processing'
    and lease_owner = p_worker_id
  for update;
  if not found then
    raise exception 'privacy deletion request is not owned' using errcode = '42501';
  end if;

  if not private.try_lock_candidate_owners(array[request_row.user_id]) then raise exception 'PRIVACY_OWNER_BUSY' using errcode='55P03';end if;
  select plan.storage_objects,plan.created_at into storage_objects,first_at
  from private.privacy_deletion_plans plan
  where plan.request_id = request_row.id;

  if not found then
    select coalesce(jsonb_agg(jsonb_build_object(
      'storageKey', storage_key,
      'checksum', checksum,
      'bytes', bytes
    )), '[]'::jsonb)
    into storage_objects
    from public.resume_versions
    where owner_id = request_row.user_id;

    if not exists(select 1 from private.owned_ai_deletion_dispositions where owner_id=request_row.user_id)
      and exists(select 1 from public.data_requests d join public.privacy_request_steps s on s.request_id=d.id
        where d.user_id=request_row.user_id and d.kind='deletion' and s.step_key='database' and s.status='completed')
      then raise exception 'OWNED_AI_DISPOSITION_HISTORICAL_REPAIR' using errcode='23514';end if;
    first_at:=clock_timestamp();
    insert into private.privacy_deletion_plans (request_id, storage_objects,created_at)
    values (request_row.id, storage_objects,first_at);
  end if;

  -- Candidate rows and the durable object plan commit atomically. A retry can
  -- therefore continue deleting the same objects after database rows are gone.
  insert into private.owned_ai_deletion_dispositions(owner_id,first_request_id,prepared_at,expires_at,phase)
    values(request_row.user_id,request_row.id,first_at,first_at+interval '720 hours','prepared') on conflict(owner_id) do nothing;
  perform private.capture_owned_ai_operation_dispositions(request_row.user_id,null,request_row.id,null);
  perform private.retire_initial_feedback_publications(request_row.user_id,null,request_row.id,null);
  delete from public.analyses where owner_id = request_row.user_id;
  delete from public.jobs where owner_id = request_row.user_id;
  delete from public.resumes where owner_id = request_row.user_id;
  delete from public.consents where user_id = request_row.user_id;
  delete from public.memberships where user_id = request_row.user_id;
  delete from public.profiles where id = request_row.user_id;

  update public.privacy_request_steps
  set status = 'completed', completed_at = timezone('utc', now())
  where request_id = request_row.id and step_key = 'database';

  return jsonb_build_object(
    'storageObjects', storage_objects,
    'databaseDeletedAt', timezone('utc', now())
  );
end;

public.complete_retention_item:
declare selected private.retention_items%rowtype;item_row private.retention_items%rowtype;root_row public.resumes%rowtype;
begin
 select * into selected from private.retention_items where id=p_item_id;
 if not found then return false;end if;
 if selected.status='deleted' then return true;end if;
 if private.owned_ai_disposition_ready() is not true then raise exception 'RETENTION_SOURCE_UNAVAILABLE' using errcode='23514';end if;
 if not private.try_lock_candidate_owners(array[selected.owner_id]) then raise exception 'PRIVACY_OWNER_BUSY' using errcode='55P03';end if;
 -- Re-read terminal state after owner acquisition BEFORE requiring a parent:
 -- another completion may have committed both deletion and parent cascade.
 select * into item_row from private.retention_items where id=p_item_id for update skip locked;
 if not found then
  if exists(select 1 from private.retention_items where id=p_item_id) then raise exception 'RETENTION_ITEM_BUSY' using errcode='55P03';end if;
  return false;
 end if;
 if (item_row.owner_id,item_row.resume_id,item_row.storage_key) is distinct from (selected.owner_id,selected.resume_id,selected.storage_key)
  then raise exception 'RETENTION_ITEM_IDENTITY_CONFLICT' using errcode='23514';end if;
 if item_row.status='deleted' then return true;end if;
 root_row:=private.r17_lock_root(item_row.owner_id,item_row.resume_id);
 if root_row.status<>'deleted' or not exists(select 1 from public.resume_versions v where v.resume_id=root_row.id and v.owner_id=root_row.owner_id
   and v.organization_id=root_row.organization_id and v.storage_key=item_row.storage_key
   and v.storage_key=private.r17_storage_key(v.organization_id,v.resume_id,v.id))
  then raise exception 'RETENTION_PARENT_REPAIR_REQUIRED' using errcode='23514';end if;
 update private.retention_items set status='deleted',completed_at=clock_timestamp(),last_error_code=null where id=p_item_id and status in ('queued','failed');
 if not found then raise exception 'RETENTION_ITEM_STATE' using errcode='23514';end if;
 -- Missing/unenrolled actual versions prevent BOTH publication retirement and
 -- parent cascade, even when every recorded work item is already deleted.
 if private.r17_root_covered(root_row.owner_id,root_row.id,root_row.organization_id) is true then
  perform private.retire_initial_feedback_publications(root_row.owner_id,root_row.id,null,item_row.id);
  -- Recheck coverage under the same owner/root/source locks immediately before DELETE.
  delete from public.resumes r where r.id=root_row.id and r.owner_id=root_row.owner_id and r.status='deleted'
    and private.r17_root_covered(root_row.owner_id,root_row.id,root_row.organization_id) is true;
  if not found then raise exception 'RETENTION_COVERAGE_CHANGED' using errcode='23514';end if;
 end if;
 return true;
end;

